@module samplePage  src=samplePage.lua  loc=68  mode=chunk  self=sp
@deps cm, ds, cmgr, chrome, gui, facade

# Imports
  @require fs = 'fs'  @ 11
      @contract  builds the substack (sm/sv local, only sv leaves); lifecycle drives sm/sv directly  @ 8
      @contract  owns its active track: the renderer's picker sets sv  @ 9
      @contract  render hooks delegate to sampleRender  @ 10
  @require util = 'util'  @ 12

# Constructed sub-instances
  @construct sm = util.instantiate('sampleManager')  @ 23
  @construct sv = util.instantiate('sampleView')  @ 24
  @construct sr = util.instantiate('sampleRender')  @ 25

# Private state
  @state sp = {}  @ 28

# Functions held in tables
  @held sample.setTrack(track)  @ 60

# Public API (sp:*)
  -- Page lifecycle (track ops on sv, JSFX poll on sm)
  @api sp:bind()  @ 37-44
      -- The shared cm is re-keyed by whichever page is active, so re-assert ours each
      -- time even when sv already remembers a track -- a prior tracker unbind nulled it.
      @contract  bind re-keys cm to the page's track on every activation (seeds a default on the first)  @ 34
  @api sp:setTrack(track)  @ 47-49
      @contract  setTrack re-keys cm to the given track via sv; the sample facade and the picker drive it  @ 46
  @api sp:unbind()  @ 52
      @contract  unbind reverts any preview-in-place but leaves cm and sv state alone — the next bind can resume on the same track  @ 51
  @api sp:tick()  @ 55-58
      @contract  tick runs every frame regardless of active page; watchPath then sm:tick  @ 54
  -- Page interface — render delegates to the renderer
  @api sp:toolbarSegments()  @ 63
  @api sp:renderBody(ctx, w, h, dispatch)  @ 64
  @api sp:statusSegments()  @ 65
  @api sp:focusState()  @ 66

# Uses (outbound edges)
  @use call    facade.publish  @ <load>:60
  @use call    sm:tick  @ tick:57
  @use call    sm:watchPath  @ tick:56
  @use call    sr:closeTransients  @ unbind:52
  @use call    sr:focusState  @ focusState:66
  @use call    sr:renderBody  @ renderBody:64
  @use call    sr:statusSegments  @ statusSegments:65
  @use call    sr:toolbarSegments  @ toolbarSegments:63
  @use call    sv:getTrack  @ bind:38
  @use call    sv:listTracks  @ bind:40
  @use call    sv:setTrack  @ bind:43 setTrack:48
  @use call    util.instantiate  @ <load>:23,24,25
  @use require fs  @ <load>:11
  @use require sampleManager  @ <load>:23
  @use require sampleRender  @ <load>:25
  @use require sampleView  @ <load>:24
  @use require util  @ <load>:12

# Calls (intra-file)
  @call sp:setTrack  @ sample.setTrack:60

# REAPER API surface
  @reaper ImGui_GetBuiltinPath
  @reaper MB

# Fields (r read / w write incl. constructor keys)
  @field r ImGui_GetBuiltinPath  @ 14
  @field r chrome  @ 19
  @field w chrome  @ 26
  @field r cm  @ 19
  @field w cm  @ 23,24,26
  @field r cmgr  @ 19
  @field w cmgr  @ 26
  @field r ds  @ 19
  @field w ds  @ 23,24,26
  @field r facade  @ 19
  @field r fileOps  @ 23
  @field w fileOps  @ 23
  @field r gui  @ 19
  @field w gui  @ 26
  @field w setTrack  @ sample.setTrack:60
  @field w sm  @ 24
  @field w sv  @ 26
  @field r track  @ bind:41
